import math

def sum_of_divisors(m):
    """Calculates sigma(m), the sum of all positive divisors of m."""
    if m <= 0:
        return 0
    s = 0
    for i in range(1, int(math.sqrt(m)) + 1):
        if m % i == 0:
            s += i
            if i * i != m:
                s += m // i
    return s

