from collections import Counter

def prime_factorization(n):
    factors = Counter()
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] += 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] += 1
    return factors

def sigma(n, factors):
    sum_div = 1
    for p, k in factors.items():
        # Formula: (p^(k+1) - 1) / (p - 1)
        sum_div *= (p**(k+1) - 1) // (p - 1)
    return sum_div

def is_perfect_square(n):
