    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

def check_m_properties(m):
    factors = prime_factorization(m)

    # 1. Composite (not prime and not 1)
    if len(factors) == 1 and list(factors.values())[0] == 1:
        return False # m is prime
    if m == 1:
        return False

    # 2. Not prime power
    is_prime_power = len(factors) == 1
    if is_prime_power:
        return False

    # 3. Not square-free (at least one exponent >= 2)
    is_square_free = all(k == 1 for k in factors.values())
    if is_square_free:
        return False

    return True

