def solve_permutation_backtrack(m, divisors):
    n = len(divisors)

    # We use a list of boolean flags to represent which divisors have been used
    used = [False] * n

    def backtrack(current_sum, used_count):
        if used_count == n:
            # Final sum must also be a square (guaranteed if all previous prefix sums were squares)
            # This check is redundant but harmless.
            return True 

        for i in range(n):
            if not used[i]:
                next_divisor = divisors[i]
                next_sum = current_sum + next_divisor

                if is_perfect_square(next_sum):
                    used[i] = True
                    if backtrack(next_sum, used_count + 1):
                        return True
                    used[i] = False # Backtrack
        return False

    # Start the search. Since a_1 must be a square divisor, we iterate over them.
    square_divisors = [d for d in divisors if is_perfect_square(d)]

    for d1 in square_divisors:
        # Initialize for a_1
        used = [False] * n
        d1_index = divisors.index(d1)
        used[d1_index] = True

        if backtrack(d1, 1):
            return True

    return False

